class Solution {
public:
    long long countValidSubstrings(string s) {
        long long ans = 0;
        int lastA = -1, lastAB = -1, lastABC = -1;
        int n = (int)s.size();
        for (int r = 0; r < n; r++) {
            char c = s[r];
            if (c == 'a') {
                lastA = r;
            } else if (c == 'b') {
                if (lastA > lastAB) lastAB = lastA;
            } else {
                if (lastAB > lastABC) lastABC = lastAB;
            }
            ans += (long long)(r - lastABC);
        }
        return ans;
    }
};
